  'https://citizenshiprightsafrica.org/wp-content/uploads/Burkina-Faso-Loi-no.012-2025-ALT-portant-Code-des-personnes-et-de-la-famille.pdf',
  array['famille', 'personnes', 'état civil', 'nom', 'domicile', '2025'],
  array[]::text[],
  now())
